        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        const errors = await response.json();
        return errors;
    } catch (error) {
        if (error.name === 'AbortError') {
            mw.log.warn('[CodeMirror] Lint request aborted.');
        } else {
            mw.log.warn('[CodeMirror] Error during lint request:', error);
        }
        return null;
    }
}

function abortRequest() {
    controller.abort();
}

